const headers = $json.headers || {};
const source = $json.body && Object.keys($json.body).length ? $json.body : $json;
const jwt = ((headers.authorization || headers.Authorization || '').replace('Bearer ', '')).trim();
const admin_key = (headers['x-admin-key'] || headers['X-ADMIN-KEY'] || '').toString().trim();
const ip = (headers['x-forwarded-for'] || '').toString();
const user_agent = (headers['user-agent'] || headers['User-Agent'] || '').toString();
const accion = (source.accion || '').toString().trim();
const paso_documentId = (source.paso_documentId || '').toString().trim();
const nombre_oficial = source.nombre_oficial;
const latitud = source.latitud;
const longitud = source.longitud;
const region = source.region;
const altitud = source.altitud;
const codigo_fuente = source.codigo_fuente;
const motivo = source.motivo;
const habilitado_para = source.habilitado_para;
const nuevo_estado = (source.nuevo_estado || '').toString().toLowerCase().trim();
const accionesValidas = ['actualizar', 'crear', 'softdelete', 'forzar_estado'];
const estadosValidos = ['habilitado', 'precaucion', 'cerrado', 'suspendido'];
const errores = [];
if (!jwt) errores.push('Falta JWT');
if (!admin_key) errores.push('Falta X-ADMIN-KEY');
if (!accion || !accionesValidas.includes(accion)) errores.push('accion debe ser: actualizar, crear, softdelete o forzar_estado');
if (accion !== 'crear' && !paso_documentId) errores.push('Falta paso_documentId');
if (accion === 'forzar_estado') {
  if (!nuevo_estado) errores.push('Falta nuevo_estado');
  if (nuevo_estado && !estadosValidos.includes(nuevo_estado)) errores.push('nuevo_estado invalido: debe ser habilitado, precaucion, cerrado o suspendido');
}
if (latitud !== undefined && latitud !== null && latitud !== '' && (isNaN(Number(latitud)) || Number(latitud) < -90 || Number(latitud) > 90)) errores.push('latitud invalida');
if (longitud !== undefined && longitud !== null && longitud !== '' && (isNaN(Number(longitud)) || Number(longitud) < -180 || Number(longitud) > 180)) errores.push('longitud invalida');
return [{ json: { jwt, admin_key, ip, user_agent, accion, paso_documentId, nombre_oficial, latitud, longitud, region, altitud, codigo_fuente, motivo, habilitado_para, nuevo_estado, errores, entrada_valida: errores.length === 0 } }];

const ultimo = $json.data?.[0] || null;
const previo = ((ultimo?.estado_normalizado || ultimo?.estado_general || '') + '').toLowerCase();
const nuevo = $('Validar Entrada').item.json.nuevo_estado;
const cambio_requerido = previo !== nuevo;
return [{ json: {
  ultimo_estado: previo || null,
  nuevo_estado: nuevo,
  cambio_requerido,
  motivo: $('Validar Entrada').item.json.motivo,
  paso_documentId: $('Validar Entrada').item.json.paso_documentId,
  actor: $('Execute WF00-Validar-Administrador').item.json.usuario
} }];

