{
  data: {
    id_paso: {
      connect: [
        { documentId: $('Comparar Estado').item.json.paso_documentId }
      ]
    },
    fecha_reporte: new Date().toISOString(),
    estado_general: $('Comparar Estado').item.json.nuevo_estado,
    fuente: 'panel_admin',
    mensaje_original: $('Comparar Estado').item.json.motivo,
    creado_en: new Date().toISOString(),
    origen_tipo: 'manual',
    motivo_estado: $('Comparar Estado').item.json.motivo,
    nivel_riesgo_calc: $('Comparar Estado').item.json.nuevo_estado === 'cerrado' || $('Comparar Estado').item.json.nuevo_estado === 'suspendido'
      ? 'alto'
      : ($('Comparar Estado').item.json.nuevo_estado === 'precaucion' ? 'medio' : 'bajo'),
    confianza_extraccion: 1,
    es_programado: false,
    fecha_vigencia_desde: new Date().toISOString(),
    fecha_vigencia_hasta: null
  }
}
}}

